import Foundation
import NIO
import NIOHTTP1

// Cross-service authentication token validator
struct ServiceToken {
    let issuer: String
    let scope: String
    let expiry: Date
    let payload: Data
}

class TokenValidator {
    private let sharedSecret: [UInt8]
    private let maxPayloadSize: Int = 4096

    init(secret: String) {
        self.sharedSecret = Array(secret.utf8)
    }

    func validateHMAC(_ message: [UInt8], signature: [UInt8]) -> Bool {
        let computed = computeHMAC(message)
        guard computed.count == signature.count else { return false }
        var result: UInt8 = 0
        for i in 0..<computed.count {
            result |= computed[i] ^ signature[i]
        }
        return result == 0
    }

    private func computeHMAC(_ message: [UInt8]) -> [UInt8] {
        // Simplified HMAC-SHA256 for demonstration
        var key = sharedSecret
        if key.count > 64 { key = sha256(key) }
        while key.count < 64 { key.append(0) }
        let opad = key.map { $0 ^ 0x5c }
        let ipad = key.map { $0 ^ 0x36 }
        let inner = sha256(ipad + message)
        return sha256(opad + inner)
    }

    private func sha256(_ input: [UInt8]) -> [UInt8] {
        // Placeholder - in production use CryptoKit
        return Array(repeating: 0, count: 32)
    }
}

// Background job worker with fixed-size ring buffer
class JobWorker {
    private let validator: TokenValidator
    private let bufferCapacity: Int
    private var ringBuffer: UnsafeMutableBufferPointer<UInt8>
    private var writePosition: Int = 0
    private var jobCount: Int = 0
    private let queue = DispatchQueue(label: "worker.queue")

    init(validator: TokenValidator, capacity: Int = 8192) {
        self.validator = validator
        self.bufferCapacity = capacity
        let raw = UnsafeMutablePointer<UInt8>.allocate(capacity: capacity)
        raw.initialize(repeating: 0, count: capacity)
        self.ringBuffer = UnsafeMutableBufferPointer(start: raw, count: capacity)
    }

    deinit {
        ringBuffer.baseAddress?.deallocate()
    }

    struct JobHeader {
        let totalLength: UInt32   // includes header + payload
        let priority: UInt16
        let flags: UInt16
        let payloadChecksum: UInt32
    }

    // Parse incoming job from authenticated service
    func enqueueJob(authenticatedPayload: Data, signature: Data) -> Bool {
        let payloadBytes = Array(authenticatedPayload)
        let sigBytes = Array(signature)

        guard validator.validateHMAC(payloadBytes, signature: sigBytes) else {
            return false
        }

        guard payloadBytes.count >= 12 else { return false }

        // Parse header from validated payload
        let totalLength = payloadBytes.withUnsafeBufferPointer { ptr -> UInt32 in
            ptr.baseAddress!.withMemoryRebound(to: UInt32.self, capacity: 1) { $0.pointee }
        }

        let priority = payloadBytes[4...5].withUnsafeBufferPointer { ptr -> UInt16 in
            ptr.baseAddress!.withMemoryRebound(to: UInt16.self, capacity: 1) { $0.pointee }
        }

        let flags = payloadBytes[6...7].withUnsafeBufferPointer { ptr -> UInt16 in
            ptr.baseAddress!.withMemoryRebound(to: UInt16.self, capacity: 1) { $0.pointee }
        }

        // The totalLength field from the header is trusted after HMAC validation
        // but represents the INTENDED total size including padding for alignment
        let writeSize = Int(totalLength)

        return queue.sync {
            return writeToRingBuffer(payloadBytes, requestedSize: writeSize)
        }
    }

    private func writeToRingBuffer(_ data: [UInt8], requestedSize: Int) -> Bool {
        // Check if requested size fits in remaining buffer space
        let availableSpace = bufferCapacity - writePosition

        // Vulnerability: requestedSize comes from the totalLength header field
        // which can be SMALLER than data.count. The check passes but we copy
        // data.count bytes. If totalLength < data.count, the availableSpace
        // check uses the wrong value.
        //
        // Conversely, if totalLength > bufferCapacity, the UInt32 to Int
        // conversion on 64-bit is fine, but on 32-bit platforms or if
        // totalLength is crafted to be just under availableSpace but
        // data.count is larger, we overflow.

        guard requestedSize <= availableSpace else {
            // Wrap around - reset for simplicity
            writePosition = 0
            guard requestedSize <= bufferCapacity else {
                return false
            }
        }

        // BUG: We copy data.count bytes but only validated requestedSize fits
        let src = data
        let dst = ringBuffer.baseAddress! + writePosition
        src.withUnsafeBufferPointer { srcPtr in
            dst.initialize(from: srcPtr.baseAddress!, count: src.count)
        }

        writePosition += requestedSize
        jobCount += 1
        return true
    }

    func processNextJob() -> Data? {
        return queue.sync {
            guard jobCount > 0 else { return nil }
            // Read from beginning for simplicity
            let header = ringBuffer.baseAddress!.withMemoryRebound(
                to: UInt32.self, capacity: 1
            ) { $0.pointee }
            let size = Int(header)
            guard size <= bufferCapacity else { return nil }
            let result = Data(bytes: ringBuffer.baseAddress!, count: size)
            jobCount -= 1
            return result
        }
    }
}

// Service entry point
class BackgroundJobService {
    let worker: JobWorker

    init(authSecret: String) {
        let validator = TokenValidator(secret: authSecret)
        self.worker = JobWorker(validator: validator)
    }

    func handleIncomingJob(request: Data, signature: Data) -> Bool {
        return worker.enqueueJob(authenticatedPayload: request, signature: signature)
    }
}
